{{(() => {
  const en = appsmith.store.bo_lang === 'en';
  const n = (x) => { const v = Number(String(x ?? '').replace(',', '.')); return v > 0 ? v : null; };
  const f = (v) => String(Math.round(v * 1000) / 1000).replace('.', ',');
  const parts = [(en ? 'Qty: ' : 'Бр.: ') + currentItem.quantity];
  if (n(currentItem.weight) !== null) parts.push(f(n(currentItem.weight)) + (en ? ' kg' : ' кг'));
  if (n(currentItem.length) !== null && n(currentItem.width) !== null && n(currentItem.height) !== null) {
    parts.push([currentItem.length, currentItem.width, currentItem.height].map((x) => f(n(x))).join('×') + (en ? ' cm' : ' см'));
  }
  return parts.join(' · ');
})()}}
